    "question": "三つの文字を手引Bの文字に置き換えた組合せはどれか。各文字の位置を手引Aで探し、線なしなら手引Bの同じ位置、線があればそこから線の側に1マス移った位置の文字に置き換える。\n提示された文字：む（上に線）、く（右に線）、て（左に線）\n\n【手引A】\n1行：け　よ　す　は\n2行：お　む　な　た\n3行：り　く　え　み\n4行：ち　の　も　て\n\n【手引B】\n1行：S　H　M　D\n2行：K　J　Z　U\n3行：B　R　A　T\n4行：P　Q　W　E",
    "choices": {
      "ア": "HRE",
      "イ": "HRR",
      "ウ": "HRQ",
      "エ": "HRT",
      "オ": "HAW"
    },
    "answer": "オ",
    "officialAnswerNumber": 5,
    "explanation": "「む」（上に線）は手引Aの2行2列にあり、手引Bの同位置から線の側へ1マス移るとHになる。「く」（右に線）は手引Aの3行2列にあり、手引Bの同位置から線の側へ1マス移るとAになる。「て」（左に線）は手引Aの4行4列にあり、手引Bの同位置から線の側へ1マス移るとWになる。",
    "choiceExplanations": {
      "ア": "「く」（右に線）は手引Aの3行2列にあり、手引Bの同位置から線の側へ1マス移るとAになる。この選択肢の2文字目はRなので一致しない。",
      "イ": "「く」（右に線）は手引Aの3行2列にあり、手引Bの同位置から線の側へ1マス移るとAになる。この選択肢の2文字目はRなので一致しない。",
      "ウ": "「く」（右に線）は手引Aの3行2列にあり、手引Bの同位置から線の側へ1マス移るとAになる。この選択肢の2文字目はRなので一致しない。",
      "エ": "「く」（右に線）は手引Aの3行2列にあり、手引Bの同位置から線の側へ1マス移るとAになる。この選択肢の2文字目はRなので一致しない。",
      "オ": "「む」（上に線）は手引Aの2行2列にあり、手引Bの同位置から線の側へ1マス移るとHになる。同様に後の2文字を求めるとA、Wとなり、全体はHAWである。"
    },
    "explanationCoverage": "full",
    "hasImage": false,
